/**
 * Worker environment. `Env` (bindings) is generated by `wrangler types` into
 * worker-configuration.d.ts; secrets are declared here because they are not in wrangler.jsonc.
 */
declare global {
  namespace Cloudflare {
    interface Env {
      SESSION_SECRET: string;
      ENCRYPTION_KEY: string;
    }
  }
  // Newer `wrangler types` output declares a standalone global `Env` as well; augment it too.
  interface Env {
    SESSION_SECRET: string;
    ENCRYPTION_KEY: string;
  }
}

/** Who made an authenticated request: the browser session cookie or a native device token. */
export type Principal = { kind: 'session' } | { kind: 'device'; deviceId: string };

export type AppEnv = {
  Bindings: Env;
  Variables: {
    /** Set by the auth middleware on authenticated requests. */
    authenticated: boolean;
    /** Set by the auth middleware: null on open routes (they resolve it themselves when needed). */
    principal: Principal | null;
  };
};

// `wrangler types` narrows DEMO_MODE to the literal in wrangler.jsonc ("0"); tests and dev set "1".
export const isDemo = (env: Env): boolean => (env.DEMO_MODE as string) === '1';
